"use strict";
let age = 25;
console.log(age);
// Integer
let marks = 90;
console.log(marks);
// Percentage
let percentage = 82.9;
console.log(percentage);
// Negative number
let temp = -80.02;
console.log(temp);
// NaN (Not a Number)
let result = NaN;
// let result:number = 0/0;
console.log(result);
// Infinity Number
let data = 10 / 0;
console.log(data);
// ADD
let a = 10;
let b = 20;
console.log(a + b); // We can perform subtraction, multiplication and modulus also
// Function 
function add(a, b) {
    return a + b;
}
console.log(add(10, 20)); // O/P => 30
console.log(10 + "20"); // O/P => 1020
